  constraint challenge_participation_marks_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint challenge_participation_marks_pkey PRIMARY KEY (challenge_id, creator_id, threshold)
);
alter table public.challenge_participation_marks enable row level security;

create table public.challenge_reminders_sent (
  challenge_id uuid not null,
  creator_id uuid not null,
