  constraint challenge_reminders_sent_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint challenge_reminders_sent_pkey PRIMARY KEY (challenge_id, creator_id, days_before)
);
alter table public.challenge_reminders_sent enable row level security;

-- Reusable challenge briefs. Shared across every admin; the payload is challenge form state with no dates, status or ids in it.
create table public.challenge_templates (
  id uuid default gen_random_uuid() not null,
  name text not null,
  created_by uuid,
  community_id uuid,
  payload jsonb default '{}'::jsonb not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint challenge_templates_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 80))),
  constraint challenge_templates_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE SET NULL,
  constraint challenge_templates_created_by_fkey FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint challenge_templates_pkey PRIMARY KEY (id)
);
alter table public.challenge_templates enable row level security;

create table public.challenge_voucher_day_wins (
