  reward_id uuid,
  views integer,
  created_at timestamp with time zone default now() not null,
  constraint challenge_voucher_day_wins_challenge_id_fkey FOREIGN KEY (challenge_id) REFERENCES challenges(id) ON DELETE CASCADE,
  constraint challenge_voucher_day_wins_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint challenge_voucher_day_wins_day_id_fkey FOREIGN KEY (day_id) REFERENCES challenge_voucher_days(id) ON DELETE CASCADE,
  constraint challenge_voucher_day_wins_reward_id_fkey FOREIGN KEY (reward_id) REFERENCES rewards(id) ON DELETE SET NULL,
  constraint challenge_voucher_day_wins_submission_id_fkey FOREIGN KEY (submission_id) REFERENCES submissions(id) ON DELETE SET NULL,
  constraint challenge_voucher_day_wins_pkey PRIMARY KEY (id),
  constraint challenge_voucher_day_wins_day_id_creator_id_key UNIQUE (day_id, creator_id)
);
alter table public.challenge_voucher_day_wins enable row level security;

create table public.challenge_voucher_days (
  id uuid default gen_random_uuid() not null,
  challenge_id uuid not null,
  day date not null,
  tz text not null,
  starts_at timestamp with time zone not null,
  ends_at timestamp with time zone not null,
  min_views integer default 5000 not null,
  reward_type text default 'voucher'::text not null,
  amount numeric not null,
  currency text default 'EUR'::text not null,
  max_winners integer,
  is_active boolean default true not null,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  constraint challenge_voucher_days_amount_check CHECK (((amount > (0)::numeric) AND (amount <= (1000)::numeric))),
  constraint challenge_voucher_days_max_winners_check CHECK (((max_winners IS NULL) OR (max_winners > 0))),
  constraint challenge_voucher_days_min_views_check CHECK ((min_views > 0)),
  constraint challenge_voucher_days_reward_type_check CHECK ((reward_type = ANY (ARRAY['voucher'::text, 'cash'::text]))),
  constraint challenge_voucher_days_challenge_id_fkey FOREIGN KEY (challenge_id) REFERENCES challenges(id) ON DELETE CASCADE,
  constraint challenge_voucher_days_created_by_fkey FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint challenge_voucher_days_pkey PRIMARY KEY (id),
  constraint challenge_voucher_days_challenge_id_day_key UNIQUE (challenge_id, day)
);
alter table public.challenge_voucher_days enable row level security;

create table public.challenge_weekly_winners (
  id uuid default gen_random_uuid() not null,
  challenge_id uuid not null,
