  starts_at timestamp with time zone not null,
  ends_at timestamp with time zone not null,
  submission_id uuid,
  creator_id uuid,
  views bigint,
  read_requested_at timestamp with time zone,
  locked_at timestamp with time zone,
  reward_id uuid,
  awarded_at timestamp with time zone,
  awarded_by uuid,
  created_at timestamp with time zone default now() not null,
  constraint challenge_weekly_winners_awarded_by_fkey FOREIGN KEY (awarded_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint challenge_weekly_winners_challenge_id_fkey FOREIGN KEY (challenge_id) REFERENCES challenges(id) ON DELETE CASCADE,
  constraint challenge_weekly_winners_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint challenge_weekly_winners_group_id_fkey FOREIGN KEY (group_id) REFERENCES challenge_groups(id) ON DELETE CASCADE,
  constraint challenge_weekly_winners_reward_id_fkey FOREIGN KEY (reward_id) REFERENCES rewards(id) ON DELETE SET NULL,
  constraint challenge_weekly_winners_submission_id_fkey FOREIGN KEY (submission_id) REFERENCES submissions(id) ON DELETE SET NULL,
  constraint challenge_weekly_winners_pkey PRIMARY KEY (id)
);
alter table public.challenge_weekly_winners enable row level security;

create table public.challenges (
  id uuid default gen_random_uuid() not null,
  title text not null,
  description text default ''::text not null,
  rules text default ''::text,
  hashtags text default ''::text,
  platforms text[] default '{Instagram,TikTok}'::text[],
  prize_structure jsonb default '[]'::jsonb,
  start_date timestamp with time zone not null,
  end_date timestamp with time zone not null,
  status text default 'draft'::text not null,
  reminder_48h_sent boolean default false not null,
  reminder_24h_sent boolean default false not null,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  publish_at timestamp with time zone,
  results_status text default 'none'::text not null,
  results_updated_at timestamp with time zone,
  vouchers_given integer default 0 not null,
  participation_threshold integer,
  participation_prize text,
  market text,
  format text default 'monthly'::text,
  audience text default 'general'::text,
  prize_amount numeric(10,2),
  prize_currency text default 'GBP'::text,
  winners_count integer,
  prize_type text,
  content_type text,
  objective text default 'views'::text,
  cpm_target numeric(10,2) default 0.50,
  community_id uuid,
  scoring text default 'prize'::text not null,
  threshold_mode text default 'highest'::text not null,
  winners_published_at timestamp with time zone,
  content_note text,
  participation_cap integer,
  participation_reward_type text,
  participation_amount numeric,
  participation_scope text default 'everyone'::text not null,
  extra_awards jsonb default '[]'::jsonb not null,
  participation_basis text default 'entries'::text not null,
  join_bonus_points numeric,
  join_bonus_from timestamp with time zone,
  weekly_prize jsonb,
  timezone text,
  opens_at timestamp with time zone,
  closes_at timestamp with time zone,
  constraint challenges_audience_check CHECK (((audience IS NULL) OR (audience = ANY (ARRAY['general'::text, 'ugc'::text, 'vip'::text])))),
  constraint challenges_content_type_check CHECK (((content_type IS NULL) OR (content_type = ANY (ARRAY['free'::text, 'suggested'::text, 'talking'::text, 'hooks'::text, 'other'::text])))),
  constraint challenges_currency_check CHECK (((prize_currency IS NULL) OR (prize_currency = ANY (ARRAY['GBP'::text, 'EUR'::text, 'USD'::text])))),
  constraint challenges_extra_awards_is_array CHECK ((jsonb_typeof(extra_awards) = 'array'::text)),
  constraint challenges_format_check CHECK (((format IS NULL) OR (format = ANY (ARRAY['monthly'::text, 'express'::text, 'always_on'::text])))),
  constraint challenges_join_bonus_points_check CHECK (((join_bonus_points IS NULL) OR ((join_bonus_points > (0)::numeric) AND (join_bonus_points <= (1000)::numeric)))),
  constraint challenges_objective_check CHECK (((objective IS NULL) OR (objective = ANY (ARRAY['views'::text, 'videos'::text, 'creativity'::text, 'trust'::text])))),
  constraint challenges_participation_basis_check CHECK ((participation_basis = ANY (ARRAY['entries'::text, 'points'::text]))),
  constraint challenges_participation_cap_check CHECK (((participation_cap IS NULL) OR (participation_cap > 0))),
  constraint challenges_participation_reward_type_check CHECK (((participation_reward_type IS NULL) OR (participation_reward_type = ANY (ARRAY['cash'::text, 'voucher'::text])))),
  constraint challenges_participation_scope_check CHECK ((participation_scope = ANY (ARRAY['everyone'::text, 'outside_prizes'::text]))),
  constraint challenges_prize_type_check CHECK (((prize_type IS NULL) OR (prize_type = ANY (ARRAY['cash'::text, 'voucher'::text, 'cash_voucher'::text, 'product'::text, 'other'::text])))),
  constraint challenges_results_status_check CHECK ((results_status = ANY (ARRAY['none'::text, 'interim'::text, 'final'::text]))),
  constraint challenges_scoring_check CHECK ((scoring = ANY (ARRAY['prize'::text, 'points'::text, 'best_video'::text, 'total_views'::text]))),
  constraint challenges_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'ended'::text, 'archived'::text]))),
  constraint challenges_threshold_mode_check CHECK ((threshold_mode = ANY (ARRAY['highest'::text, 'cumulative'::text]))),
  constraint challenges_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE RESTRICT,
  constraint challenges_created_by_fkey FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint challenges_pkey PRIMARY KEY (id)
);
alter table public.challenges enable row level security;
comment on column public.challenges.vouchers_given is 'LEGACY. A hand-typed count, kept only for challenges that ran before participation_threshold existed. Never write to this again - challenge_voucher_counts() derives the number from the entries.';
comment on column public.challenges.participation_threshold is 'Number of videos a creator must post to earn the participation reward (null = no participation reward).';
comment on column public.challenges.participation_prize is 'The reward text shown when a creator hits participation_threshold videos.';
comment on column public.challenges.scoring is 'points = the point ledger decides it; best_video = the single highest-viewed entry; total_views = every entry added up; prize = legacy, judged by the team.';
comment on column public.challenges.winners_published_at is 'Set when an admin explicitly publishes the winners podium. Null = results may exist but the podium stays hidden.';
comment on column public.challenges.content_note is 'Free text for content_type = ''other'': the admin names the kind of video this brief wants when none of the fixed options fits. Reporting groups on content_type; this is what a person reads.';

create table public.channel_reads (
