  post_policy text default 'all'::text not null,
  visibility text default 'scope'::text not null,
  position integer default 0 not null,
  created_at timestamp with time zone default now() not null,
  constraint channels_post_policy_check CHECK ((post_policy = ANY (ARRAY['all'::text, 'staff'::text]))),
  constraint channels_visibility_check CHECK ((visibility = ANY (ARRAY['scope'::text, 'staff'::text, 'vip'::text]))),
  constraint channels_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE CASCADE,
  constraint channels_pkey PRIMARY KEY (id),
