create table public.client_error_seen (
  fingerprint text not null,
  profile_id uuid not null,
  seen_at timestamp with time zone default now() not null,
  constraint client_error_seen_profile_id_fkey FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint client_error_seen_pkey PRIMARY KEY (fingerprint, profile_id)
);
alter table public.client_error_seen enable row level security;

create table public.client_errors (
