  last_seen_at timestamp with time zone default now() not null,
  hits integer default 1 not null,
  people integer default 1 not null,
  resolved_at timestamp with time zone,
  resolved_by uuid,
  agent text,
  detail text,
  source text default 'client'::text not null,
