  constraint client_errors_pkey PRIMARY KEY (fingerprint)
);
alter table public.client_errors enable row level security;
comment on column public.client_errors.source is 'client = a crash in a creator''s browser; cron = a scheduled job; integration = an external API we read.';

create table public.collab_interests (
  id uuid default gen_random_uuid() not null,
