  constraint collab_interests_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint collab_interests_post_id_fkey FOREIGN KEY (post_id) REFERENCES collab_posts(id) ON DELETE CASCADE,
  constraint collab_interests_pkey PRIMARY KEY (id),
