  constraint collab_posts_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint collab_posts_pkey PRIMARY KEY (id)
);
alter table public.collab_posts enable row level security;
comment on column public.collab_posts.city_lat is 'Resolved once, server side, so the map never geocodes in the browser. See migration 177.';

create table public.communities (
  id uuid default gen_random_uuid() not null,
  slug text not null,
  name text not null,
  kind text default 'chapter'::text not null,
  country_codes character(2)[] default '{}'::bpchar[] not null,
  language text default 'en'::text not null,
  currency text default 'EUR'::text not null,
  timezone text default 'UTC'::text not null,
  lead_id uuid,
  is_active boolean default false not null,
  join_mode text default 'review'::text not null,
  cpm_target numeric(10,2) default 0.50 not null,
  prize_baseline numeric(10,2) default 0 not null,
  brand jsonb default '{}'::jsonb not null,
  created_at timestamp with time zone default now() not null,
  settings jsonb default '{}'::jsonb not null,
  join_policy text default 'country'::text not null,
  tagline text,
  retired_at timestamp with time zone,
  constraint communities_currency_check CHECK ((currency = ANY (ARRAY['GBP'::text, 'EUR'::text, 'USD'::text, 'SEK'::text, 'DKK'::text, 'NOK'::text, 'RON'::text, 'PLN'::text, 'CHF'::text]))),
  constraint communities_join_mode_check CHECK ((join_mode = ANY (ARRAY['review'::text, 'instant'::text]))),
  constraint communities_join_policy_check CHECK ((join_policy = ANY (ARRAY['country'::text, 'open'::text, 'invite'::text]))),
  constraint communities_kind_check CHECK ((kind = ANY (ARRAY['network'::text, 'chapter'::text]))),
  constraint communities_lead_id_fkey FOREIGN KEY (lead_id) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint communities_pkey PRIMARY KEY (id),
  constraint communities_slug_key UNIQUE (slug)
);
alter table public.communities enable row level security;
comment on column public.communities.language is 'Which language this market reads the platform in (an i18n locale code: en, es). Drives who may edit that language''s translation overrides. See migration 168.';
comment on column public.communities.join_policy is 'country = creators whose country_code is in country_codes may join themselves; open = any creator may join; invite = a manager must add them.';
comment on column public.communities.tagline is 'One line shown under the market name.';
comment on column public.communities.retired_at is 'When this market was retired. Retired markets keep all their data, disappear from creator-facing lists, and stay visible to admins.';

create table public.community_invites (
  token text default encode(gen_random_bytes(16), 'hex'::text) not null,
  community_id uuid not null,
  created_by uuid not null,
  role text default 'creator'::text not null,
  email_lock text,
  max_uses integer,
  used_count integer default 0 not null,
  expires_at timestamp with time zone,
  revoked boolean default false not null,
  created_at timestamp with time zone default now() not null,
  constraint community_invites_role_check CHECK ((role = ANY (ARRAY['creator'::text, 'manager'::text]))),
  constraint staff_invites_must_be_locked CHECK (((role <> 'manager'::text) OR ((email_lock IS NOT NULL) AND (max_uses = 1) AND (expires_at IS NOT NULL)))),
  constraint community_invites_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE CASCADE,
  constraint community_invites_created_by_fkey FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint community_invites_pkey PRIMARY KEY (token)
);
alter table public.community_invites enable row level security;

