  joined_at timestamp with time zone default now() not null,
  constraint community_members_role_check CHECK ((role = ANY (ARRAY['creator'::text, 'manager'::text]))),
  constraint community_members_status_check CHECK ((status = ANY (ARRAY['active'::text, 'pending'::text, 'left'::text, 'removed'::text]))),
  constraint community_members_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE CASCADE,
  constraint community_members_profile_id_fkey FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
