  created_at timestamp with time zone default now() not null,
  constraint connection_notes_body_check CHECK (((char_length(body) >= 1) AND (char_length(body) <= 300))),
  constraint connection_notes_author_id_fkey FOREIGN KEY (author_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint connection_notes_connection_id_fkey FOREIGN KEY (connection_id) REFERENCES connections(id) ON DELETE CASCADE,
  constraint connection_notes_pkey PRIMARY KEY (connection_id)
);
alter table public.connection_notes enable row level security;

create table public.connections (
