  constraint connections_connected_creator_id_fkey FOREIGN KEY (connected_creator_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint connections_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint connections_pkey PRIMARY KEY (id),
  constraint connections_creator_id_connected_creator_id_key UNIQUE (creator_id, connected_creator_id)
);
alter table public.connections enable row level security;

create table public.content_translations (
