alter table public.content_translations enable row level security;

create table public.conversation_invites (
  id uuid default gen_random_uuid() not null,
  conversation_id uuid not null,
  invited_profile_id uuid not null,
  invited_by uuid not null,
  status text default 'pending'::text not null,
  created_at timestamp with time zone default now() not null,
  constraint conversation_invites_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'declined'::text]))),
  constraint conversation_invites_conversation_id_fkey FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,
  constraint conversation_invites_invited_by_fkey FOREIGN KEY (invited_by) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint conversation_invites_invited_profile_id_fkey FOREIGN KEY (invited_profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint conversation_invites_pkey PRIMARY KEY (id),
  constraint conversation_invites_conversation_id_invited_profile_id_key UNIQUE (conversation_id, invited_profile_id)
);
alter table public.conversation_invites enable row level security;

