  conversation_id uuid not null,
  profile_id uuid not null,
  role text default 'member'::text not null,
  joined_at timestamp with time zone default now() not null,
  last_read_at timestamp with time zone default now() not null,
  constraint conversation_members_role_check CHECK ((role = ANY (ARRAY['owner'::text, 'member'::text]))),
  constraint conversation_members_conversation_id_fkey FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,
  constraint conversation_members_profile_id_fkey FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint conversation_members_pkey PRIMARY KEY (conversation_id, profile_id)
);
alter table public.conversation_members enable row level security;

create table public.conversations (
  id uuid default gen_random_uuid() not null,
  participant_a uuid,
  participant_b uuid,
  last_message_at timestamp with time zone,
  created_at timestamp with time zone default now() not null,
  kind text default 'direct'::text not null,
  title text,
  photo_url text,
  accent text,
  emoji text,
  created_by uuid,
  constraint chk_not_self CHECK ((participant_a <> participant_b)),
  constraint conversations_kind_chk CHECK ((kind = ANY (ARRAY['direct'::text, 'group'::text]))),
  constraint conversations_shape_chk CHECK ((((kind = 'direct'::text) AND (participant_a IS NOT NULL) AND (participant_b IS NOT NULL)) OR ((kind = 'group'::text) AND (created_by IS NOT NULL)))),
  constraint conversations_created_by_fkey FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint conversations_participant_a_fkey FOREIGN KEY (participant_a) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint conversations_participant_b_fkey FOREIGN KEY (participant_b) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint conversations_pkey PRIMARY KEY (id),
  constraint uq_conversation_pair UNIQUE (participant_a, participant_b)
);
alter table public.conversations enable row level security;
comment on column public.conversations.last_message_at is 'When the most recent message arrived. NULL means nobody has sent one yet - the inbox hides 1:1 threads in that state (see Messages.jsx). Maintained by trg_touch_conversation on direct_messages.';

create table public.creator_admin_notes (
  creator_id uuid not null,
  note text default ''::text not null,
  updated_by uuid,
  updated_at timestamp with time zone default now() not null,
  community_id uuid,
  constraint creator_admin_notes_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE RESTRICT,
  constraint creator_admin_notes_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint creator_admin_notes_updated_by_fkey FOREIGN KEY (updated_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint creator_admin_notes_pkey PRIMARY KEY (creator_id)
);
