  constraint creator_kit_assets_title_check CHECK (((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 80))),
  constraint creator_kit_assets_created_by_fkey FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE SET NULL,
