create table public.creator_photos (
  id uuid default gen_random_uuid() not null,
  creator_id uuid not null,
  photo_url text not null,
  caption text default ''::text,
  sort_order integer default 0 not null,
  created_at timestamp with time zone default now() not null,
  size text default 'small'::text not null,
  pos_x smallint,
  pos_y smallint,
  pos_w smallint,
  pos_h smallint,
  focal_x real default 0.5 not null,
  focal_y real default 0.5 not null,
  zoom real default 1 not null,
  aspect real,
  sort_order_mobile integer,
  size_mobile text,
  constraint creator_photos_crop_bounds CHECK (((focal_x >= (0)::double precision) AND (focal_x <= (1)::double precision) AND (focal_y >= (0)::double precision) AND (focal_y <= (1)::double precision) AND (zoom >= (1)::double precision) AND (zoom <= (3)::double precision))),
  constraint creator_photos_pos_bounds CHECK ((((pos_x IS NULL) OR ((pos_x >= 0) AND (pos_x <= 1000))) AND ((pos_y IS NULL) OR ((pos_y >= 0) AND (pos_y <= 32000))) AND ((pos_w IS NULL) OR ((pos_w >= 40) AND (pos_w <= 1000))) AND ((pos_h IS NULL) OR ((pos_h >= 40) AND (pos_h <= 32000))))),
  constraint creator_photos_size_check CHECK ((size = ANY (ARRAY['small'::text, 'medium'::text, 'large'::text]))),
  constraint creator_photos_size_mobile_check CHECK (((size_mobile IS NULL) OR (size_mobile = ANY (ARRAY['small'::text, 'medium'::text, 'large'::text])))),
  constraint creator_photos_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint creator_photos_pkey PRIMARY KEY (id)
);
alter table public.creator_photos enable row level security;

-- A creator's media kit. is_public puts it on the open web at /p/<slug>; show_on_profile is the smaller, separate decision to show it inside the community.
create table public.creator_portfolios (
  profile_id uuid not null,
  is_public boolean default false not null,
  slug text,
  headline text,
  intro text,
  about text,
  tools text[] default '{}'::text[] not null,
  extra_platforms jsonb default '[]'::jsonb not null,
  picks uuid[] default '{}'::uuid[] not null,
  copy jsonb default '{}'::jsonb not null,
  show_on_profile boolean default true not null,
  updated_at timestamp with time zone default now() not null,
  published_at timestamp with time zone,
  constraint creator_portfolios_slug_check CHECK (((slug IS NULL) OR (slug ~ '^[a-z0-9]([a-z0-9-]{1,38}[a-z0-9])$'::text))),
  constraint creator_portfolios_profile_id_fkey FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint creator_portfolios_pkey PRIMARY KEY (profile_id),
  constraint creator_portfolios_slug_key UNIQUE (slug)
);
alter table public.creator_portfolios enable row level security;

