  constraint direct_messages_resource_id_fkey FOREIGN KEY (resource_id) REFERENCES resources(id) ON DELETE SET NULL,
  constraint direct_messages_sender_id_fkey FOREIGN KEY (sender_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint direct_messages_submission_id_fkey FOREIGN KEY (submission_id) REFERENCES submissions(id) ON DELETE SET NULL,
  constraint direct_messages_pkey PRIMARY KEY (id)
);
alter table public.direct_messages enable row level security;
comment on column public.direct_messages.resource_id is 'A resource-library card posted into the conversation. Body is empty for these.';

