  constraint flights_duration_min_check CHECK (((duration_min IS NULL) OR ((duration_min > 0) AND (duration_min < 1200)))),
  constraint flights_from_iata_check CHECK ((from_iata ~ '^[A-Z]{3}$'::text)),
  constraint flights_not_a_loop CHECK ((from_iata <> to_iata)),
