  id uuid default gen_random_uuid() not null,
  text text not null,
  family text default 'More ideas'::text not null,
  uses integer default 1 not null,
  language text default 'en'::text not null,
  is_active boolean default true not null,
  source text default 'team'::text not null,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint hooks_source_check CHECK ((source = ANY (ARRAY['bank'::text, 'team'::text]))),
  constraint hooks_text_check CHECK (((length(btrim(text)) >= 3) AND (length(btrim(text)) <= 400))),
  constraint hooks_uses_check CHECK ((uses >= 0)),
  constraint hooks_created_by_fkey FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint hooks_pkey PRIMARY KEY (id)
);
alter table public.hooks enable row level security;

create table public.invoices (
  id uuid default gen_random_uuid() not null,
  number integer not null,
  creator_id uuid,
  creator_name text not null,
  amount numeric(10,2) not null,
  currency text not null,
  description text not null,
  issue_date date default CURRENT_DATE not null,
  bill_to text default ''::text not null,
  payment jsonb default '{}'::jsonb not null,
  notes text,
  sent_to text,
  cc text,
  status text default 'sent'::text not null,
  sent_at timestamp with time zone,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  community_id uuid,
  reward_id uuid,
  stage text default 'draft'::text not null,
  submitted_at timestamp with time zone,
  submitted_by uuid,
  decided_at timestamp with time zone,
  decided_by uuid,
  decision_note text,
  auto_generated boolean default false not null,
  paid_at timestamp with time zone,
  fx_rate numeric,
  constraint invoices_currency_check CHECK ((currency = ANY (ARRAY['GBP'::text, 'EUR'::text]))),
  constraint invoices_stage_chk CHECK ((stage = ANY (ARRAY['draft'::text, 'awaiting_approval'::text, 'approved'::text, 'rejected'::text, 'sent'::text, 'paid'::text]))),
  constraint invoices_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE RESTRICT,
  constraint invoices_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint invoices_decided_by_fkey FOREIGN KEY (decided_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint invoices_reward_id_fkey FOREIGN KEY (reward_id) REFERENCES rewards(id) ON DELETE SET NULL,
  constraint invoices_submitted_by_fkey FOREIGN KEY (submitted_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint invoices_pkey PRIMARY KEY (id),
  constraint invoices_number_key UNIQUE (number)
);
alter table public.invoices enable row level security;
comment on column public.invoices.fx_rate is 'The rate used to convert the prize amount into the payee''s currency. Null when no conversion happened.';

create table public.job_applications (
  id uuid default gen_random_uuid() not null,
  job_id uuid not null,
  creator_id uuid not null,
  pitch text not null,
  status text default 'new'::text not null,
  created_at timestamp with time zone default now() not null,
  constraint job_applications_status_check CHECK ((status = ANY (ARRAY['new'::text, 'reviewing'::text, 'contacted'::text, 'hired'::text, 'declined'::text]))),
  constraint job_applications_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint job_applications_job_id_fkey FOREIGN KEY (job_id) REFERENCES jobs(id) ON DELETE CASCADE,
  constraint job_applications_pkey PRIMARY KEY (id),
  constraint job_applications_job_id_creator_id_key UNIQUE (job_id, creator_id)
);
alter table public.job_applications enable row level security;

create table public.jobs (
  id uuid default gen_random_uuid() not null,
  title text not null,
  description text default ''::text not null,
  location text default ''::text,
  job_type text default 'Permanent'::text not null,
  apply_url text,
  status text default 'open'::text not null,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  community_id uuid,
  constraint jobs_apply_url_is_web CHECK (((apply_url IS NULL) OR (apply_url = ''::text) OR (apply_url ~* '^https?://'::text))),
  constraint jobs_status_check CHECK ((status = ANY (ARRAY['open'::text, 'closed'::text]))),
  constraint jobs_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE RESTRICT,
  constraint jobs_created_by_fkey FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint jobs_pkey PRIMARY KEY (id)
);
alter table public.jobs enable row level security;

-- Quarterly KPI targets an admin sets for a market or for Worldwide. Actual progress on the four standard metrics is never stored here - see kpi_actuals().
create table public.kpi_targets (
  id uuid default gen_random_uuid() not null,
  community_id uuid not null,
  year integer not null,
  quarter integer not null,
  metric text not null,
  label text not null,
  target_value numeric not null,
  is_automated boolean default false not null,
  current_value numeric,
  notes text,
  created_by uuid,
  updated_by uuid,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  month integer,
  basis text default 'all'::text not null,
  unit text default 'number'::text not null,
  higher_is_better boolean default true not null,
  cumulative boolean default true not null,
  constraint kpi_targets_basis_check CHECK ((basis = ANY (ARRAY['all'::text, 'global'::text]))),
  constraint kpi_targets_metric_check CHECK ((metric = ANY (ARRAY['challenges_run'::text, 'creators_recruited'::text, 'creators_participated'::text, 'views'::text, 'entries'::text, 'avg_entries_per_creator'::text, 'entries_per_challenge'::text, 'avg_creators_per_challenge'::text, 'avg_views_per_entry'::text, 'avg_views_per_creator'::text, 'videos_10k'::text, 'top_video_views'::text, 'participation_rate'::text, 'first_time_creators'::text, 'return_rate'::text, 'activation_rate'::text, 'referrals'::text, 'creators_total'::text, 'chat_messages'::text, 'game_players'::text, 'connections_made'::text, 'custom'::text]))),
  constraint kpi_targets_month_check CHECK (((month IS NULL) OR (((month >= 1) AND (month <= 12)) AND ((((month - 1) / 3) + 1) = quarter)))),
  constraint kpi_targets_quarter_check CHECK (((quarter >= 1) AND (quarter <= 4))),
  constraint kpi_targets_target_value_check CHECK ((target_value >= (0)::numeric)),
  constraint kpi_targets_unit_check CHECK ((unit = ANY (ARRAY['number'::text, 'decimal'::text, 'percent'::text, 'views'::text, 'currency'::text]))),
  constraint kpi_targets_year_check CHECK (((year >= 2020) AND (year <= 2100))),
  constraint kpi_targets_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE CASCADE,
  constraint kpi_targets_created_by_fkey FOREIGN KEY (created_by) REFERENCES profiles(id),
  constraint kpi_targets_updated_by_fkey FOREIGN KEY (updated_by) REFERENCES profiles(id),
  constraint kpi_targets_pkey PRIMARY KEY (id)
);
alter table public.kpi_targets enable row level security;

-- A creator asking to join a market they are not in. Decline carries a reason, which is sent to them - "no" with no reason is the version that makes somebody feel shut out rather than redirected.
create table public.market_join_requests (
  id uuid default gen_random_uuid() not null,
  community_id uuid not null,
  profile_id uuid not null,
  note text,
  status text default 'pending'::text not null,
  decided_by uuid,
  decided_at timestamp with time zone,
  decision_note text,
  created_at timestamp with time zone default now() not null,
  challenge_id uuid,
  language_level text,
  ties text[] default '{}'::text[] not null,
  constraint market_join_requests_language_check CHECK (((language_level IS NULL) OR (language_level = ANY (ARRAY['native'::text, 'fluent'::text, 'some'::text, 'none'::text])))),
  constraint market_join_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'declined'::text]))),
  constraint market_join_requests_challenge_id_fkey FOREIGN KEY (challenge_id) REFERENCES challenges(id) ON DELETE SET NULL,
  constraint market_join_requests_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE CASCADE,
  constraint market_join_requests_decided_by_fkey FOREIGN KEY (decided_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint market_join_requests_profile_id_fkey FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint market_join_requests_pkey PRIMARY KEY (id)
);
alter table public.market_join_requests enable row level security;
comment on column public.market_join_requests.language_level is 'How well they say they speak the market''s language: native, fluent, some, none.';
comment on column public.market_join_requests.ties is 'What ties them to the market: live, part_time, study, work, family, audience.';

create table public.market_signup_settings (
  community_id uuid not null,
  call_enabled boolean default false not null,
  call_url text,
  call_minutes integer default 15 not null,
  host_profile_id uuid,
  note text,
  updated_at timestamp with time zone default now() not null,
  updated_by uuid,
  audience text default 'community'::text not null,
  constraint market_signup_settings_audience_check CHECK ((audience = ANY (ARRAY['community'::text, 'vip'::text]))),
  constraint market_signup_settings_call_minutes_check CHECK (((call_minutes >= 5) AND (call_minutes <= 120))),
  constraint market_signup_settings_call_url_check CHECK (((call_url IS NULL) OR (call_url ~* '^https?://'::text))),
  constraint market_signup_settings_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE CASCADE,
  constraint market_signup_settings_host_profile_id_fkey FOREIGN KEY (host_profile_id) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint market_signup_settings_updated_by_fkey FOREIGN KEY (updated_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint market_signup_settings_pkey PRIMARY KEY (community_id, audience)
);
alter table public.market_signup_settings enable row level security;

create table public.message_reports (
  id uuid default gen_random_uuid() not null,
  reporter_id uuid not null,
  kind text not null,
  message_id uuid,
  dm_id uuid,
  author_id uuid,
  body_snapshot text,
  media_snapshot text,
  context text,
  reason text not null,
  details text,
  status text default 'new'::text not null,
  admin_note text,
  reviewed_by uuid,
  reviewed_at timestamp with time zone,
  created_at timestamp with time zone default now() not null,
  constraint message_reports_kind_check CHECK ((kind = ANY (ARRAY['channel'::text, 'dm'::text]))),
  constraint message_reports_reason_check CHECK ((reason = ANY (ARRAY['spam'::text, 'harassment'::text, 'hate'::text, 'explicit'::text, 'scam'::text, 'other'::text]))),
  constraint message_reports_status_check CHECK ((status = ANY (ARRAY['new'::text, 'reviewing'::text, 'actioned'::text, 'dismissed'::text]))),
  constraint message_reports_target_check CHECK ((((kind = 'channel'::text) AND (dm_id IS NULL)) OR ((kind = 'dm'::text) AND (message_id IS NULL)))),
  constraint message_reports_author_id_fkey FOREIGN KEY (author_id) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint message_reports_dm_id_fkey FOREIGN KEY (dm_id) REFERENCES direct_messages(id) ON DELETE SET NULL,
  constraint message_reports_message_id_fkey FOREIGN KEY (message_id) REFERENCES messages(id) ON DELETE SET NULL,
  constraint message_reports_reporter_id_fkey FOREIGN KEY (reporter_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint message_reports_reviewed_by_fkey FOREIGN KEY (reviewed_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint message_reports_pkey PRIMARY KEY (id)
);
alter table public.message_reports enable row level security;

create table public.messages (
  id uuid default gen_random_uuid() not null,
  channel text not null,
  sender_id uuid not null,
  body text not null,
  created_at timestamp with time zone default now() not null,
  deleted boolean default false not null,
  image_url text,
  poll_id uuid,
  game_event_id uuid,
  birthday_for uuid,
  resource_id uuid,
  reply_to uuid,
  audio_url text,
  video_url text,
  pinned boolean default false not null,
  leaderboard_challenge_id uuid,
  community_id uuid,
  channel_id uuid,
  edited_at timestamp with time zone,
  media_w smallint,
  media_h smallint,
  leaderboard_group_id uuid,
  intro jsonb,
  leaderboard_view text,
  constraint messages_body_check CHECK (((char_length(body) <= 4000) AND ((body <> ''::text) OR (image_url IS NOT NULL) OR (poll_id IS NOT NULL) OR (game_event_id IS NOT NULL) OR (birthday_for IS NOT NULL) OR (resource_id IS NOT NULL) OR (audio_url IS NOT NULL) OR (video_url IS NOT NULL) OR (leaderboard_challenge_id IS NOT NULL)))),
  constraint messages_channel_check CHECK (((channel ~ '^[a-z0-9-]{2,32}:[a-z0-9_]{2,32}$'::text) OR (channel ~ '^[a-z0-9_]{2,32}$'::text))),
  constraint messages_leaderboard_view_check CHECK (((leaderboard_view IS NULL) OR (leaderboard_view = ANY (ARRAY['board'::text, 'podium'::text])))),
  constraint messages_birthday_for_fkey FOREIGN KEY (birthday_for) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint messages_channel_id_fkey FOREIGN KEY (channel_id) REFERENCES channels(id) ON DELETE CASCADE,
  constraint messages_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE RESTRICT,
  constraint messages_game_event_id_fkey FOREIGN KEY (game_event_id) REFERENCES game_events(id) ON DELETE SET NULL,
  constraint messages_leaderboard_challenge_id_fkey FOREIGN KEY (leaderboard_challenge_id) REFERENCES challenges(id) ON DELETE SET NULL,
  constraint messages_leaderboard_group_id_fkey FOREIGN KEY (leaderboard_group_id) REFERENCES challenge_groups(id) ON DELETE SET NULL,
  constraint messages_poll_id_fkey FOREIGN KEY (poll_id) REFERENCES polls(id) ON DELETE SET NULL,
  constraint messages_reply_to_fkey FOREIGN KEY (reply_to) REFERENCES messages(id) ON DELETE SET NULL,
  constraint messages_resource_id_fkey FOREIGN KEY (resource_id) REFERENCES resources(id) ON DELETE CASCADE,
  constraint messages_sender_id_fkey FOREIGN KEY (sender_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint messages_pkey PRIMARY KEY (id)
);
alter table public.messages enable row level security;
comment on column public.messages.community_id is 'Denormalised from channels.community_id for RLS speed. Kept in sync by trigger; never write it directly.';
comment on column public.messages.intro is 'A structured introduction (the introductions room). body keeps a plain-text copy for search and notifications.';

create table public.milestone_criteria (
  id uuid default gen_random_uuid() not null,
  milestone_id uuid not null,
  metric text not null,
  threshold numeric not null,
  unit text default 'days'::text not null,
  created_at timestamp with time zone default now() not null,
  constraint milestone_criteria_metric_check CHECK ((metric = ANY (ARRAY['views'::text, 'videos'::text, 'referrals'::text, 'challenges'::text, 'days'::text, 'podiums'::text, 'best_video'::text]))),
  constraint milestone_criteria_threshold_check CHECK ((threshold > (0)::numeric)),
  constraint milestone_criteria_unit_check CHECK ((unit = ANY (ARRAY['days'::text, 'months'::text, 'years'::text]))),
  constraint milestone_criteria_milestone_id_fkey FOREIGN KEY (milestone_id) REFERENCES milestones(id) ON DELETE CASCADE,
  constraint milestone_criteria_pkey PRIMARY KEY (id)
);
alter table public.milestone_criteria enable row level security;

-- The milestone ladder. Fully admin-editable: thresholds, rewards and order are data.
create table public.milestones (
  id uuid default gen_random_uuid() not null,
  title text not null,
  description text,
  reward text,
  reward_kind text default 'status'::text not null,
  icon text default 'flag'::text not null,
  sort_order integer default 0 not null,
  is_active boolean default true not null,
  created_at timestamp with time zone default now() not null,
  role_title text,
  voucher_amount numeric,
  voucher_currency text default 'EUR'::text,
  items jsonb default '[]'::jsonb not null,
  constraint milestones_reward_kind_check CHECK ((reward_kind = ANY (ARRAY['merch'::text, 'voucher'::text, 'role'::text, 'other'::text]))),
  constraint milestones_pkey PRIMARY KEY (id)
);
alter table public.milestones enable row level security;

create table public.notifications (
