  title text not null,
  body text default ''::text,
  link text default ''::text,
  read boolean default false not null,
  created_at timestamp with time zone default now() not null,
  constraint notifications_type_check CHECK ((type = ANY (ARRAY['challenge'::text, 'announcement'::text, 'results'::text, 'reward'::text, 'deadline'::text, 'connection'::text, 'dm'::text, 'event'::text, 'application'::text, 'chat'::text, 'submission'::text, 'deletion'::text, 'referral'::text, 'new_member'::text, 'inactive'::text, 'feedback'::text, 'collab'::text, 'mention'::text, 'daily_streak'::text, 'daily_reminder'::text, 'board_answer'::text, 'report'::text, 'event_reminder'::text, 'event_rating'::text, 'reaction'::text, 'community'::text, 'vip'::text, 'rank'::text]))),
  constraint notifications_recipient_id_fkey FOREIGN KEY (recipient_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint notifications_pkey PRIMARY KEY (id)
);
alter table public.notifications enable row level security;

create table public.onboarding_progress (
  id bigint generated always as identity not null,
  profile_id uuid,
  step smallint not null,
  reached_at timestamp with time zone default now() not null,
  signed_up timestamp with time zone,
  country_code text,
  person uuid,
  constraint onboarding_progress_step_check CHECK (((step >= 1) AND (step <= 8))),
  constraint onboarding_progress_profile_id_fkey FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint onboarding_progress_pkey PRIMARY KEY (id)
);
alter table public.onboarding_progress enable row level security;

create table public.ops_health_samples (
  taken_at timestamp with time zone default now() not null,
  stats_since timestamp with time zone,
  exec_ms double precision,
  blks_hit bigint,
  blks_read bigint,
  conns integer,
  max_conns integer,
  readings jsonb default '{}'::jsonb not null,
  constraint ops_health_samples_pkey PRIMARY KEY (taken_at)
);
alter table public.ops_health_samples enable row level security;

create table public.ops_stat_snapshots (
  taken_at timestamp with time zone default now() not null,
  stats_since timestamp with time zone,
  queryid bigint,
  query text,
  calls bigint,
  total_ms double precision,
  rows bigint,
  blks_read bigint,
  blks_dirtied bigint,
  blks_written bigint,
  temp_written bigint,
  wal_bytes numeric
);
alter table public.ops_stat_snapshots enable row level security;

create table public.owner_only_rpcs (
  proname text not null,
  why text not null,
  constraint owner_only_rpcs_pkey PRIMARY KEY (proname)
);
alter table public.owner_only_rpcs enable row level security;

create table public.point_awards (
  id uuid default gen_random_uuid() not null,
  community_id uuid not null,
  challenge_id uuid,
  creator_id uuid not null,
  rule_id uuid,
  submission_id uuid,
  points numeric(10,2) not null,
  reason text default ''::text not null,
  is_auto boolean default true not null,
  awarded_by uuid,
  created_at timestamp with time zone default now() not null,
  constraint point_awards_awarded_by_fkey FOREIGN KEY (awarded_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint point_awards_challenge_id_fkey FOREIGN KEY (challenge_id) REFERENCES challenges(id) ON DELETE CASCADE,
  constraint point_awards_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE CASCADE,
  constraint point_awards_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint point_awards_rule_id_fkey FOREIGN KEY (rule_id) REFERENCES point_rules(id) ON DELETE SET NULL,
  constraint point_awards_submission_id_fkey FOREIGN KEY (submission_id) REFERENCES submissions(id) ON DELETE CASCADE,
  constraint point_awards_pkey PRIMARY KEY (id)
);
alter table public.point_awards enable row level security;

create table public.point_rules (
  id uuid default gen_random_uuid() not null,
  community_id uuid not null,
  challenge_id uuid,
  kind text not null,
  label text not null,
  points numeric(10,2) default 0 not null,
  threshold integer,
  max_points numeric(10,2),
  position integer default 0 not null,
  is_active boolean default true not null,
  created_at timestamp with time zone default now() not null,
  prompt text,
  min_views integer,
  period_days integer,
  starts_at timestamp with time zone,
  ends_at timestamp with time zone,
  constraint point_rules_kind_check CHECK ((kind = ANY (ARRAY['per_post'::text, 'views_threshold'::text, 'bonus'::text, 'total_views_threshold'::text, 'platform_spread'::text, 'consistency'::text, 'collab'::text]))),
  constraint point_rules_min_views_check CHECK (((min_views IS NULL) OR (min_views >= 0))),
  constraint point_rules_period_days_check CHECK (((period_days IS NULL) OR (period_days > 0))),
  constraint point_rules_window_order CHECK (((starts_at IS NULL) OR (ends_at IS NULL) OR (ends_at > starts_at))),
  constraint point_rules_challenge_id_fkey FOREIGN KEY (challenge_id) REFERENCES challenges(id) ON DELETE CASCADE,
  constraint point_rules_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE CASCADE,
  constraint point_rules_pkey PRIMARY KEY (id)
);
alter table public.point_rules enable row level security;
comment on column public.point_rules.prompt is 'Bonus rules only. The yes/no question a creator is asked when they submit an entry. A bonus with a prompt is claimed by the creator and awarded automatically; a bonus without one is awarded by an admin by hand.';
comment on column public.point_rules.min_views is 'Claimable bonuses only. The entry must have at least this many logged views before the bonus pays out. Null means it pays as soon as it is claimed. The claim is kept either way - only the award waits - so a creator ticks the box once and the point arrives when the video gets there.';
comment on column public.point_rules.starts_at is 'Bonus only: entries submitted before this do not earn it. Null = from the challenge start.';
comment on column public.point_rules.ends_at is 'Bonus only: entries submitted after this do not earn it. Null = until the deadline.';

create table public.points_recalc_queue (
  challenge_id uuid not null,
