  community_id uuid,
  constraint polls_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE RESTRICT,
  constraint polls_created_by_fkey FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint polls_pkey PRIMARY KEY (id)
);
alter table public.polls enable row level security;

create table public.profiles (
  id uuid not null,
  name text default ''::text not null,
  age integer,
  photo_url text,
  bio text default ''::text,
  about text default ''::text,
  instagram_url text,
  tiktok_url text,
  youtube_url text,
  other_links jsonb default '[]'::jsonb,
  languages text[] default '{}'::text[],
  countries_visited text[] default '{}'::text[],
  is_admin boolean default false not null,
  status text default 'active'::text not null,
  onboarded boolean default false not null,
  created_at timestamp with time zone default now() not null,
  city text default ''::text,
  country text default ''::text,
  referral_code text,
  referred_by uuid,
  dob date,
  notif_prefs jsonb default '{"dm": true, "chat": true, "event": true, "reward": true, "results": true, "challenge": true, "connection": true, "announcement": true}'::jsonb not null,
  email_opt_in boolean default true not null,
  email_prefs jsonb default '{"dm": false, "chat": false, "event": true, "reward": true, "results": true, "challenge": true, "connection": false, "application": true, "announcement": true}'::jsonb not null,
  favourite_quote text default ''::text,
  deletion_requested_at timestamp with time zone,
  challenge_reminder_days integer[] default '{7,3}'::integer[] not null,
  inactive_alerted_at timestamp with time zone,
  accepted_at timestamp with time zone,
  is_test boolean default false not null,
  last_seen_at timestamp with time zone,
  city_lat double precision,
  city_lng double precision,
  bucket_list jsonb default '[]'::jsonb not null,
  connect_gate_done boolean default false not null,
  resources_seen_at timestamp with time zone,
  referral_clicks integer default 0 not null,
  show_on_map boolean default true not null,
  dark_mode boolean default false not null,
  country_code character(2),
  platform_role text default 'none'::text not null,
  role_title text,
  timezone text,
  timezone_seen text,
  tour_completed_at timestamp with time zone,
  facebook_url text,
  admin_prefs jsonb default '{}'::jsonb not null,
  is_sandbox boolean default false not null,
  earned_role text,
  linkedin_url text,
  locale text,
  followed_up_at timestamp with time zone,
  submitted_at timestamp with time zone,
  team_application boolean default false not null,
  requested_role_title text,
  team_invite_id uuid,
  is_vip boolean default false not null,
  vip_kind text,
  onboarding_call_opened_at timestamp with time zone,
  onboarding_call_booked_at timestamp with time zone,
  signup_source jsonb,
  onboarding_call_at timestamp with time zone,
  onboarding_call_ref text,
  constraint profiles_age_check CHECK (((age IS NULL) OR ((age >= 16) AND (age <= 100)))),
  constraint profiles_locale_check CHECK (((locale IS NULL) OR (locale = ANY (ARRAY['en'::text, 'es'::text, 'pt'::text, 'de'::text, 'ro'::text])))),
  constraint profiles_platform_role_check CHECK ((platform_role = ANY (ARRAY['none'::text, 'global_admin'::text, 'owner'::text]))),
  constraint profiles_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'active'::text, 'muted'::text, 'suspended'::text, 'declined'::text]))),
  constraint profiles_id_fkey FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE,
  constraint profiles_referred_by_fkey FOREIGN KEY (referred_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint profiles_team_invite_id_fkey FOREIGN KEY (team_invite_id) REFERENCES team_invites(id) ON DELETE SET NULL,
  constraint profiles_pkey PRIMARY KEY (id)
);
alter table public.profiles enable row level security;
comment on column public.profiles.dob is 'DEPRECATED and always NULL. Birthdays live in creator_private.dob; this column is kept only so a browser running an older bundle does not error on select(*). Drop it once that is no longer possible.';
comment on column public.profiles.city_lat is 'Latitude of profiles.city, geocoded via the geocode edge function.';
comment on column public.profiles.city_lng is 'Longitude of profiles.city, geocoded via the geocode edge function.';
comment on column public.profiles.show_on_map is 'When false, the creator is hidden from the PUBLIC landing-page community map. They still appear on the in-app community map.';
comment on column public.profiles.dark_mode is 'Per-creator preference: dark theme for the community app.';
comment on column public.profiles.country_code is 'ISO 3166-1 alpha-2. Machine-readable counterpart to the free-text country. Drives chapter suggestion at signup. Never overwrites country, which stays as the creator-typed display value.';
comment on column public.profiles.role_title is 'Display-only job title for Tryp.com team members. Never grants permission.';
comment on column public.profiles.timezone is 'IANA zone to show times in, or null for "follow this device".';
comment on column public.profiles.timezone_seen is 'The device zone last acknowledged, so the travel prompt fires once per move.';
comment on column public.profiles.admin_prefs is 'Per-admin UI preferences. `panel_order` is an array of admin tool ids in the order that admin arranged them; unknown ids are ignored and new tools append, so shipping a new tool never breaks a saved layout.';
comment on column public.profiles.is_sandbox is 'The single account "View as creator" drops an admin into. Joined to every market automatically, hidden from the map, and refused permission to post.';
comment on column public.profiles.linkedin_url is 'Public LinkedIn profile URL. Same shape and same RLS as instagram_url etc.';
comment on column public.profiles.locale is 'The language this creator has chosen for the app (''en'', ''es''). Null means they have never chosen and the browser decides. Per ACCOUNT, so the choice follows them from a phone to a laptop; lib/i18n also keeps a per-device copy so the screen changes before the round trip.';
comment on column public.profiles.followed_up_at is 'When an admin recorded sending a follow-up email to a half-finished signup. Set by hand from /admin/applications; there is no automation behind it.';
comment on column public.profiles.submitted_at is 'When the creator finished and submitted their application (onboarded false -> true). Null for rows that predate migration 218; fall back to created_at.';
comment on column public.profiles.team_application is 'Signed up through a team invite link. Marks them in the applications queue; grants nothing.';
comment on column public.profiles.vip_kind is 'Read-only mirror: the kind of the paid programme this creator is active in (vip | official), or null.';
comment on column public.profiles.signup_source is 'First-touch source of the sign-up: {source, medium, campaign, landing, at}. Written once by the applicant.';

-- The ONLY functions anon may execute. Adding a row here is a deliberate decision to publish data to the open internet; the event trigger no_new_function_is_public enforces everything else.
create table public.public_rpc_allowlist (
  proname text not null,
  reason text not null,
  constraint public_rpc_allowlist_pkey PRIMARY KEY (proname)
);
alter table public.public_rpc_allowlist enable row level security;

create table public.push_events (
  id bigint generated always as identity not null,
  notification_id uuid,
  recipient_id uuid,
  type text,
  event text not null,
  status_code integer,
  host text,
  detail text,
  created_at timestamp with time zone default now() not null,
  constraint push_events_event_check CHECK ((event = ANY (ARRAY['sent'::text, 'failed'::text, 'removed'::text, 'no_device'::text, 'muted'::text, 'delivered'::text, 'clicked'::text]))),
  constraint push_events_pkey PRIMARY KEY (id)
);
alter table public.push_events enable row level security;

create table public.push_subscriptions (
  id uuid default gen_random_uuid() not null,
  user_id uuid not null,
  endpoint text not null,
  p256dh text not null,
  auth text not null,
  created_at timestamp with time zone default now() not null,
  constraint push_subscriptions_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint push_subscriptions_pkey PRIMARY KEY (id),
  constraint push_subscriptions_endpoint_key UNIQUE (endpoint)
);
alter table public.push_subscriptions enable row level security;

create table public.rank_alerts (
  challenge_id uuid not null,
  creator_id uuid not null,
  last_rank integer,
  sent_at timestamp with time zone default now() not null,
  constraint rank_alerts_challenge_id_fkey FOREIGN KEY (challenge_id) REFERENCES challenges(id) ON DELETE CASCADE,
  constraint rank_alerts_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint rank_alerts_pkey PRIMARY KEY (challenge_id, creator_id)
);
alter table public.rank_alerts enable row level security;

create table public.reactions (
  id uuid default gen_random_uuid() not null,
  message_id uuid not null,
  creator_id uuid not null,
  emoji text not null,
  created_at timestamp with time zone default now() not null,
  constraint reactions_emoji_check CHECK ((char_length(emoji) <= 8)),
  constraint reactions_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint reactions_message_id_fkey FOREIGN KEY (message_id) REFERENCES messages(id) ON DELETE CASCADE,
  constraint reactions_pkey PRIMARY KEY (id),
  constraint reactions_message_id_creator_id_emoji_key UNIQUE (message_id, creator_id, emoji)
);
alter table public.reactions enable row level security;

create table public.recruit_links (
  id uuid default gen_random_uuid() not null,
  code text not null,
  owner_id uuid,
  kind text not null,
  label text,
  clicks integer default 0 not null,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  archived_at timestamp with time zone,
  constraint recruit_links_code_check CHECK ((code ~ '^[a-z0-9][a-z0-9-]{1,38}[a-z0-9]$'::text)),
  constraint recruit_links_kind_check CHECK ((kind = ANY (ARRAY['community'::text, 'vip'::text]))),
  constraint recruit_links_label_check CHECK ((char_length(label) <= 120)),
  constraint recruit_links_created_by_fkey FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint recruit_links_owner_id_fkey FOREIGN KEY (owner_id) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint recruit_links_pkey PRIMARY KEY (id),
  constraint recruit_links_code_key UNIQUE (code)
);
alter table public.recruit_links enable row level security;

create table public.referrals (
  id uuid default gen_random_uuid() not null,
  referrer_id uuid,
  referred_name text not null,
  referred_contact text default ''::text,
  note text default ''::text,
  status text default 'new'::text not null,
  created_at timestamp with time zone default now() not null,
  community_id uuid,
  constraint referrals_status_check CHECK ((status = ANY (ARRAY['new'::text, 'contacted'::text, 'joined'::text, 'declined'::text]))),
  constraint referrals_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE RESTRICT,
  constraint referrals_referrer_id_fkey FOREIGN KEY (referrer_id) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint referrals_pkey PRIMARY KEY (id)
);
alter table public.referrals enable row level security;

create table public.resource_bookmarks (
  resource_id uuid not null,
  creator_id uuid not null,
  created_at timestamp with time zone default now() not null,
  constraint resource_bookmarks_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint resource_bookmarks_resource_id_fkey FOREIGN KEY (resource_id) REFERENCES resources(id) ON DELETE CASCADE,
  constraint resource_bookmarks_pkey PRIMARY KEY (resource_id, creator_id)
);
alter table public.resource_bookmarks enable row level security;

create table public.resources (
  id uuid default gen_random_uuid() not null,
  title text not null,
  body text default ''::text,
  file_url text,
  category text default 'Tips'::text not null,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  community_id uuid,
  links jsonb default '[]'::jsonb not null,
  constraint resources_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE RESTRICT,
  constraint resources_created_by_fkey FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint resources_pkey PRIMARY KEY (id)
);
alter table public.resources enable row level security;
comment on column public.resources.links is 'Array of { label, url }. Ordered as the author arranged them.';

create table public.results (
  id uuid default gen_random_uuid() not null,
  challenge_id uuid not null,
  creator_id uuid not null,
  final_views integer default 0 not null,
  rank integer not null,
  created_at timestamp with time zone default now() not null,
  community_id uuid,
  group_id uuid,
  total_views integer default 0 not null,
  constraint results_challenge_id_fkey FOREIGN KEY (challenge_id) REFERENCES challenges(id) ON DELETE CASCADE,
  constraint results_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE RESTRICT,
  constraint results_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint results_group_id_fkey FOREIGN KEY (group_id) REFERENCES challenge_groups(id) ON DELETE SET NULL,
  constraint results_pkey PRIMARY KEY (id),
  constraint results_challenge_id_creator_id_key UNIQUE (challenge_id, creator_id)
);
alter table public.results enable row level security;
comment on column public.results.total_views is 'The creator''s combined logged views for this challenge. Carried on every board regardless of what the board RANKS on, because "how many people saw it" is worth showing next to a points total.';

create table public.rewards (
  id uuid default gen_random_uuid() not null,
  creator_id uuid not null,
  challenge_id uuid,
  reward_type text not null,
  amount numeric(10,2) not null,
  currency text default 'GBP'::text not null,
  status text default 'pending'::text not null,
  payment_notes text default ''::text,
  distributed_at timestamp with time zone,
  created_at timestamp with time zone default now() not null,
  community_id uuid,
  source text default 'challenge'::text not null,
  referred_creator_id uuid,
  milestone_id uuid,
  prize_slot text,
  voucher_code text,
  used_at timestamp with time zone,
  issued_via text,
  voucher_group uuid,
  used_by uuid,
  constraint rewards_issued_via_check CHECK (((issued_via IS NULL) OR (issued_via = 'chat'::text))),
  constraint rewards_reward_type_check CHECK ((reward_type = ANY (ARRAY['cash'::text, 'voucher'::text]))),
  constraint rewards_source_check CHECK ((source = ANY (ARRAY['challenge'::text, 'referral'::text, 'manual'::text, 'milestone'::text, 'vip'::text]))),
  constraint rewards_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'distributed'::text]))),
  constraint rewards_challenge_id_fkey FOREIGN KEY (challenge_id) REFERENCES challenges(id) ON DELETE SET NULL,
  constraint rewards_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE RESTRICT,
  constraint rewards_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint rewards_milestone_id_fkey FOREIGN KEY (milestone_id) REFERENCES milestones(id) ON DELETE SET NULL,
  constraint rewards_referred_creator_id_fkey FOREIGN KEY (referred_creator_id) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint rewards_used_by_fkey FOREIGN KEY (used_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint rewards_pkey PRIMARY KEY (id)
);
alter table public.rewards enable row level security;
comment on column public.rewards.voucher_code is 'The voucher code the team issued for this reward, shown to the creator on /rewards.';
comment on column public.rewards.used_at is 'When the creator ticked the voucher as used. Their own record; set via set_reward_used().';
comment on column public.rewards.issued_via is 'chat = the voucher was handed over outside the platform (before codes lived here).';
comment on column public.rewards.voucher_group is 'Rows sharing one combined voucher code. Amounts stay on the rows; the wallet shows the group as one ticket.';

-- A message written now and posted later into ANY room. channel/channel_id/community_id are replayed verbatim into messages, so the same row works for a legacy channel and for a market room. tz is the zone the author typed the time in, kept for display only.
create table public.scheduled_announcements (
  id uuid default gen_random_uuid() not null,
  body text not null,
  scheduled_for timestamp with time zone not null,
  created_by uuid,
  posted_at timestamp with time zone,
  created_at timestamp with time zone default now() not null,
  community_id uuid,
  channel text default 'announcements'::text,
  channel_id uuid,
  tz text,
  cancelled_at timestamp with time zone,
  constraint scheduled_announcements_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE RESTRICT,
  constraint scheduled_announcements_created_by_fkey FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint scheduled_announcements_pkey PRIMARY KEY (id)
);
alter table public.scheduled_announcements enable row level security;

create table public.scheduled_approvals (
  profile_id uuid not null,
  market_slugs text[] default '{}'::text[] not null,
  vip_programme uuid,
  approve_at timestamp with time zone not null,
  scheduled_by uuid,
  created_at timestamp with time zone default now() not null,
  constraint scheduled_approvals_profile_id_fkey FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint scheduled_approvals_scheduled_by_fkey FOREIGN KEY (scheduled_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint scheduled_approvals_vip_programme_fkey FOREIGN KEY (vip_programme) REFERENCES vip_programmes(id) ON DELETE SET NULL,
  constraint scheduled_approvals_pkey PRIMARY KEY (profile_id)
);
alter table public.scheduled_approvals enable row level security;

create table public.streak_freezes (
  profile_id uuid not null,
  day_key integer not null,
  created_at timestamp with time zone default now() not null,
  constraint streak_freezes_profile_id_fkey FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint streak_freezes_pkey PRIMARY KEY (profile_id, day_key)
);
alter table public.streak_freezes enable row level security;

create table public.submission_bonus_claims (
  id uuid default gen_random_uuid() not null,
  submission_id uuid not null,
  rule_id uuid not null,
  creator_id uuid not null,
  challenge_id uuid not null,
  created_at timestamp with time zone default now() not null,
  constraint submission_bonus_claims_challenge_id_fkey FOREIGN KEY (challenge_id) REFERENCES challenges(id) ON DELETE CASCADE,
  constraint submission_bonus_claims_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint submission_bonus_claims_rule_id_fkey FOREIGN KEY (rule_id) REFERENCES point_rules(id) ON DELETE CASCADE,
  constraint submission_bonus_claims_submission_id_fkey FOREIGN KEY (submission_id) REFERENCES submissions(id) ON DELETE CASCADE,
  constraint submission_bonus_claims_pkey PRIMARY KEY (id),
  constraint submission_bonus_claims_submission_id_rule_id_key UNIQUE (submission_id, rule_id)
);
alter table public.submission_bonus_claims enable row level security;

create table public.submission_disqualifications (
  id uuid not null,
  challenge_id uuid not null,
  creator_id uuid not null,
  snapshot jsonb not null,
  reason text not null,
  disqualified_by uuid,
  disqualified_at timestamp with time zone default now() not null,
  constraint submission_disqualifications_challenge_id_fkey FOREIGN KEY (challenge_id) REFERENCES challenges(id) ON DELETE CASCADE,
  constraint submission_disqualifications_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint submission_disqualifications_disqualified_by_fkey FOREIGN KEY (disqualified_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint submission_disqualifications_pkey PRIMARY KEY (id)
);
alter table public.submission_disqualifications enable row level security;

create table public.submission_duplicates (
  id uuid not null,
  challenge_id uuid not null,
  creator_id uuid,
  platform_video_id text,
  kept_submission_id uuid,
  snapshot jsonb not null,
  detected_at timestamp with time zone default now() not null,
  constraint submission_duplicates_challenge_id_fkey FOREIGN KEY (challenge_id) REFERENCES challenges(id) ON DELETE CASCADE,
  constraint submission_duplicates_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint submission_duplicates_pkey PRIMARY KEY (id)
);
alter table public.submission_duplicates enable row level security;

create table public.submission_feedback (
  submission_id uuid not null,
  body text not null,
  author_id uuid not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint submission_feedback_body_check CHECK (((length(btrim(body)) >= 1) AND (length(btrim(body)) <= 2000))),
  constraint submission_feedback_author_id_fkey FOREIGN KEY (author_id) REFERENCES profiles(id),
  constraint submission_feedback_submission_id_fkey FOREIGN KEY (submission_id) REFERENCES submissions(id) ON DELETE CASCADE,
  constraint submission_feedback_pkey PRIMARY KEY (submission_id)
);
alter table public.submission_feedback enable row level security;

create table public.submissions (
  id uuid default gen_random_uuid() not null,
  creator_id uuid not null,
  challenge_id uuid not null,
  platform text not null,
  video_url text not null,
  caption text default ''::text,
  logged_views integer,
  submitted_at timestamp with time zone default now() not null,
  community_id uuid,
  platform_video_id text,
  views_source text default 'manual'::text not null,
  views_synced_at timestamp with time zone,
  views_sync_error text,
  views_approx boolean default false not null,
  thumbnail_url text,
  posted_at timestamp with time zone,
  collab_of uuid,
  screen_text text,
  removed_seen_at timestamp with time zone,
  constraint submissions_platform_check CHECK ((platform = ANY (ARRAY['Instagram'::text, 'TikTok'::text, 'YouTube'::text, 'Facebook'::text, 'Other'::text]))),
  constraint submissions_video_url_is_web CHECK ((video_url ~* '^https?://'::text)),
  constraint submissions_views_source_check CHECK ((views_source = ANY (ARRAY['manual'::text, 'tiktok'::text, 'instagram'::text, 'youtube'::text, 'facebook'::text]))),
  constraint submissions_challenge_id_fkey FOREIGN KEY (challenge_id) REFERENCES challenges(id) ON DELETE CASCADE,
  constraint submissions_collab_of_fkey FOREIGN KEY (collab_of) REFERENCES submissions(id) ON DELETE SET NULL,
  constraint submissions_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE RESTRICT,
  constraint submissions_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint submissions_pkey PRIMARY KEY (id)
);
alter table public.submissions enable row level security;
comment on column public.submissions.community_id is 'Denormalised from challenges.community_id for RLS speed. Kept in sync by trigger; never write it directly.';
comment on column public.submissions.platform_video_id is 'Canonical numeric TikTok id / Instagram shortcode, cached the first time a share-sheet short link is followed so later syncs are a single request.';
comment on column public.submissions.views_sync_error is 'Why the last read produced nothing: no_video_id, not_a_video, not_on_reels_tab, blocked, no_count_in_page, needs_key, fetch_failed, unsupported, bad_url. Null when the last read was clean.';
comment on column public.submissions.views_approx is 'The stored count is rounded, not exact. Facebook logged-out only states "5.6K views". Type an exact number by hand when a ranking turns on it.';
comment on column public.submissions.thumbnail_url is 'Permanent public URL of the cover frame in the video-thumbs bucket. Written only by the thumb-cache edge function. Never a platform CDN URL: those are signed and expire, which is the whole reason this column exists.';

create table public.survey_responses (
  id uuid default gen_random_uuid() not null,
  survey_id uuid not null,
  profile_id uuid,
  answers jsonb default '{}'::jsonb not null,
  declined boolean default false not null,
  created_at timestamp with time zone default now() not null,
  sample_name text,
  sample_market text,
  constraint survey_responses_who_check CHECK (((profile_id IS NOT NULL) OR (sample_name IS NOT NULL))),
  constraint survey_responses_profile_id_fkey FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint survey_responses_survey_id_fkey FOREIGN KEY (survey_id) REFERENCES surveys(id) ON DELETE CASCADE,
  constraint survey_responses_pkey PRIMARY KEY (id),
  constraint survey_responses_survey_id_profile_id_key UNIQUE (survey_id, profile_id)
);
alter table public.survey_responses enable row level security;

create table public.surveys (
  id uuid default gen_random_uuid() not null,
  title text not null,
  intro text,
  questions jsonb default '[]'::jsonb not null,
  audience text default 'everyone'::text not null,
  community_ids uuid[] default '{}'::uuid[] not null,
  challenge_id uuid,
  mode text default 'until_done'::text not null,
  allow_decline boolean default true not null,
  status text default 'draft'::text not null,
  starts_at timestamp with time zone,
  ends_at timestamp with time zone,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  is_test boolean default false not null,
  thanks text,
  timing text default 'now'::text not null,
  constraint surveys_audience_check CHECK ((audience = ANY (ARRAY['everyone'::text, 'markets'::text, 'challenge'::text, 'vip'::text]))),
  constraint surveys_mode_check CHECK ((mode = ANY (ARRAY['until_done'::text, 'once'::text]))),
  constraint surveys_questions_check CHECK ((jsonb_typeof(questions) = 'array'::text)),
