  constraint vip_perk_awards_perk_id_fkey FOREIGN KEY (perk_id) REFERENCES vip_perks(id) ON DELETE CASCADE,
  constraint vip_perk_awards_profile_id_fkey FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint vip_perk_awards_pkey PRIMARY KEY (perk_id, profile_id)
);
alter table public.vip_perk_awards enable row level security;

create table public.vip_perks (
  id uuid default gen_random_uuid() not null,
  programme_id uuid,
  kind text default 'perk'::text not null,
  title text not null,
  description text,
  image_url text,
  metric text default 'lifetime_views'::text not null,
  threshold bigint default 0 not null,
  sort integer default 0 not null,
  active boolean default true not null,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  reward_kind text default 'none'::text not null,
  reward_amount numeric,
  constraint vip_perks_description_check CHECK (((description IS NULL) OR (char_length(description) <= 1000))),
  constraint vip_perks_kind_check CHECK ((kind = ANY (ARRAY['perk'::text, 'trip'::text, 'milestone'::text]))),
  constraint vip_perks_metric_check CHECK ((metric = ANY (ARRAY['lifetime_views'::text, 'lifetime_videos'::text, 'months_active'::text, 'best_video_views'::text, 'streak_months'::text, 'manual'::text]))),
  constraint vip_perks_reward_amount_check CHECK (((reward_amount IS NULL) OR (reward_amount >= (0)::numeric))),
  constraint vip_perks_reward_kind_check CHECK ((reward_kind = ANY (ARRAY['none'::text, 'cash'::text, 'voucher'::text]))),
  constraint vip_perks_threshold_check CHECK ((threshold >= 0)),
  constraint vip_perks_title_check CHECK (((char_length(title) >= 1) AND (char_length(title) <= 120))),
  constraint vip_perks_created_by_fkey FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint vip_perks_programme_id_fkey FOREIGN KEY (programme_id) REFERENCES vip_programmes(id) ON DELETE CASCADE,
  constraint vip_perks_pkey PRIMARY KEY (id)
);
alter table public.vip_perks enable row level security;

create table public.vip_programmes (
  id uuid default gen_random_uuid() not null,
  community_id uuid not null,
  name text not null,
  currency text default 'EUR'::text not null,
  cpm numeric(8,4) default 0.25 not null,
  tiers jsonb default '[]'::jsonb not null,
  min_payout numeric(10,2) default 10 not null,
  monthly_cap numeric(10,2),
  budget_monthly numeric(10,2),
  window_days integer default 60 not null,
  terms_version integer default 1 not null,
  terms text,
  active boolean default true not null,
  created_at timestamp with time zone default now() not null,
  is_default boolean default false not null,
  accent text,
  tagline text,
  welcome_message text,
  request_days integer default 10 not null,
  req_on boolean default true not null,
  req_videos integer default 5 not null,
  req_single_views bigint default 20000 not null,
  voucher_min numeric default 10 not null,
  auto_approve boolean default true not null,
  kind text default 'vip'::text not null,
  constraint vip_programmes_accent_check CHECK (((accent IS NULL) OR (accent ~ '^#[0-9a-fA-F]{6}$'::text))),
  constraint vip_programmes_budget_monthly_check CHECK (((budget_monthly IS NULL) OR (budget_monthly >= (0)::numeric))),
  constraint vip_programmes_cpm_check CHECK ((cpm >= (0)::numeric)),
  constraint vip_programmes_kind_check CHECK ((kind = ANY (ARRAY['vip'::text, 'official'::text]))),
  constraint vip_programmes_min_payout_check CHECK ((min_payout >= (0)::numeric)),
  constraint vip_programmes_monthly_cap_check CHECK (((monthly_cap IS NULL) OR (monthly_cap >= (0)::numeric))),
  constraint vip_programmes_req_single_views_check CHECK ((req_single_views >= 0)),
  constraint vip_programmes_req_videos_check CHECK ((req_videos >= 0)),
  constraint vip_programmes_request_days_check CHECK (((request_days >= 1) AND (request_days <= 31))),
  constraint vip_programmes_tagline_check CHECK (((tagline IS NULL) OR (char_length(tagline) <= 120))),
  constraint vip_programmes_voucher_min_check CHECK ((voucher_min >= (0)::numeric)),
  constraint vip_programmes_welcome_message_check CHECK (((welcome_message IS NULL) OR (char_length(welcome_message) <= 1000))),
  constraint vip_programmes_window_days_check CHECK (((window_days >= 1) AND (window_days <= 365))),
  constraint vip_programmes_community_id_fkey FOREIGN KEY (community_id) REFERENCES communities(id) ON DELETE RESTRICT,
  constraint vip_programmes_pkey PRIMARY KEY (id)
);
alter table public.vip_programmes enable row level security;
comment on column public.vip_programmes.kind is 'vip = the VIP community of a market; official = the official Tryp.com content creators of a market (own contract, own board, own bonuses).';

create table public.vip_requirement_reviews (
  month_id uuid not null,
  profile_id uuid not null,
  programme_id uuid not null,
  videos integer default 0 not null,
  best_views bigint default 0 not null,
  met boolean not null,
  decision text,
  note text,
  decided_by uuid,
  decided_at timestamp with time zone,
  created_at timestamp with time zone default now() not null,
  constraint vip_requirement_reviews_decision_check CHECK ((decision = ANY (ARRAY['keep'::text, 'warn'::text, 'pause'::text, 'remove'::text]))),
  constraint vip_requirement_reviews_decided_by_fkey FOREIGN KEY (decided_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint vip_requirement_reviews_month_id_fkey FOREIGN KEY (month_id) REFERENCES vip_months(id) ON DELETE CASCADE,
  constraint vip_requirement_reviews_profile_id_fkey FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint vip_requirement_reviews_programme_id_fkey FOREIGN KEY (programme_id) REFERENCES vip_programmes(id) ON DELETE CASCADE,
  constraint vip_requirement_reviews_pkey PRIMARY KEY (month_id, profile_id)
);
alter table public.vip_requirement_reviews enable row level security;

create table public.vip_sheet_history (
  id uuid default gen_random_uuid() not null,
  programme_id uuid not null,
  profile_id uuid,
  name text not null,
  year integer not null,
  month integer not null,
  views bigint default 0 not null,
  earned numeric(12,2) default 0 not null,
  cpm numeric,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  constraint vip_sheet_history_month_check CHECK (((month >= 1) AND (month <= 12))),
  constraint vip_sheet_history_views_check CHECK ((views >= 0)),
  constraint vip_sheet_history_year_check CHECK (((year >= 2020) AND (year <= 2100))),
  constraint vip_sheet_history_created_by_fkey FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint vip_sheet_history_profile_id_fkey FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint vip_sheet_history_programme_id_fkey FOREIGN KEY (programme_id) REFERENCES vip_programmes(id) ON DELETE CASCADE,
  constraint vip_sheet_history_pkey PRIMARY KEY (id),
  constraint vip_sheet_history_programme_id_name_year_month_key UNIQUE (programme_id, name, year, month)
);
alter table public.vip_sheet_history enable row level security;

create table public.vip_statements (
  id uuid default gen_random_uuid() not null,
  programme_id uuid not null,
  month_id uuid not null,
  profile_id uuid not null,
  views bigint default 0 not null,
  videos integer default 0 not null,
  cpm numeric(8,4),
  base numeric(12,2) default 0 not null,
  cap numeric(10,2),
  cap_applied boolean default false not null,
  bonuses jsonb default '[]'::jsonb not null,
  adjustments jsonb default '[]'::jsonb not null,
  rollover_in numeric(12,2) default 0 not null,
  rollover_out numeric(12,2) default 0 not null,
  total numeric(12,2) default 0 not null,
  currency text default 'EUR'::text not null,
  flags jsonb default '[]'::jsonb not null,
  status text default 'draft'::text not null,
  reward_id uuid,
  voucher_reward_ids uuid[] default '{}'::uuid[] not null,
  invoice_id uuid,
  approved_by uuid,
  approved_at timestamp with time zone,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint vip_statements_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'approved'::text, 'void'::text]))),
  constraint vip_statements_approved_by_fkey FOREIGN KEY (approved_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint vip_statements_invoice_id_fkey FOREIGN KEY (invoice_id) REFERENCES invoices(id) ON DELETE SET NULL,
  constraint vip_statements_month_id_fkey FOREIGN KEY (month_id) REFERENCES vip_months(id) ON DELETE CASCADE,
  constraint vip_statements_profile_id_fkey FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint vip_statements_programme_id_fkey FOREIGN KEY (programme_id) REFERENCES vip_programmes(id) ON DELETE CASCADE,
  constraint vip_statements_reward_id_fkey FOREIGN KEY (reward_id) REFERENCES rewards(id) ON DELETE SET NULL,
  constraint vip_statements_pkey PRIMARY KEY (id),
  constraint vip_statements_month_id_profile_id_key UNIQUE (month_id, profile_id)
);
alter table public.vip_statements enable row level security;

create table public.vip_video_answers (
  video_id uuid not null,
  question_id uuid not null,
  answers text[] default '{}'::text[] not null,
  answered_at timestamp with time zone default now() not null,
  constraint vip_video_answers_question_id_fkey FOREIGN KEY (question_id) REFERENCES vip_video_questions(id) ON DELETE CASCADE,
  constraint vip_video_answers_video_id_fkey FOREIGN KEY (video_id) REFERENCES vip_videos(id) ON DELETE CASCADE,
  constraint vip_video_answers_pkey PRIMARY KEY (video_id, question_id)
);
alter table public.vip_video_answers enable row level security;

create table public.vip_video_claims (
  video_id uuid not null,
  rule_id uuid not null,
  status text default 'claimed'::text not null,
  created_at timestamp with time zone default now() not null,
  created_by uuid,
  decided_by uuid,
  decided_at timestamp with time zone,
  constraint vip_video_claims_status_check CHECK ((status = ANY (ARRAY['claimed'::text, 'confirmed'::text, 'rejected'::text]))),
  constraint vip_video_claims_created_by_fkey FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint vip_video_claims_decided_by_fkey FOREIGN KEY (decided_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint vip_video_claims_rule_id_fkey FOREIGN KEY (rule_id) REFERENCES vip_bonus_rules(id) ON DELETE CASCADE,
  constraint vip_video_claims_video_id_fkey FOREIGN KEY (video_id) REFERENCES vip_videos(id) ON DELETE CASCADE,
  constraint vip_video_claims_pkey PRIMARY KEY (video_id, rule_id)
);
alter table public.vip_video_claims enable row level security;

create table public.vip_video_questions (
  id uuid default gen_random_uuid() not null,
  programme_id uuid,
  kind text default 'vip'::text not null,
  question text not null,
  options text[] default '{}'::text[] not null,
  multiple boolean default false not null,
  required boolean default true not null,
  audience text default 'all'::text not null,
  profile_ids uuid[] default '{}'::uuid[] not null,
  active boolean default true not null,
  position integer default 0 not null,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint vip_video_questions_audience_check CHECK ((audience = ANY (ARRAY['all'::text, 'some'::text]))),
  constraint vip_video_questions_kind_check CHECK ((kind = ANY (ARRAY['vip'::text, 'official'::text]))),
  constraint vip_video_questions_question_check CHECK (((length(btrim(question)) >= 3) AND (length(btrim(question)) <= 200))),
  constraint vip_video_questions_created_by_fkey FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint vip_video_questions_programme_id_fkey FOREIGN KEY (programme_id) REFERENCES vip_programmes(id) ON DELETE CASCADE,
  constraint vip_video_questions_pkey PRIMARY KEY (id)
);
alter table public.vip_video_questions enable row level security;

create table public.vip_videos (
  id uuid default gen_random_uuid() not null,
  profile_id uuid not null,
  programme_id uuid not null,
  platform text not null,
  video_url text not null,
  caption text,
  platform_video_id text,
  logged_views bigint default 0 not null,
  views_source text,
  views_synced_at timestamp with time zone,
  views_sync_error text,
  views_approx boolean,
  thumbnail_url text,
  posted_at timestamp with time zone,
  submitted_at timestamp with time zone default now() not null,
  status text default 'tracking'::text not null,
  disqualified_reason text,
  disqualified_at timestamp with time zone,
  disqualified_by uuid,
  screen_text text,
  constraint vip_videos_platform_check CHECK ((platform = ANY (ARRAY['Instagram'::text, 'TikTok'::text, 'YouTube'::text, 'Facebook'::text, 'Other'::text]))),
  constraint vip_videos_status_check CHECK ((status = ANY (ARRAY['tracking'::text, 'disqualified'::text]))),
  constraint vip_videos_video_url_is_web CHECK ((video_url ~* '^https?://'::text)),
  constraint vip_videos_views_source_check CHECK ((views_source = ANY (ARRAY['manual'::text, 'tiktok'::text, 'instagram'::text, 'youtube'::text, 'facebook'::text]))),
  constraint vip_videos_disqualified_by_fkey FOREIGN KEY (disqualified_by) REFERENCES profiles(id) ON DELETE SET NULL,
  constraint vip_videos_profile_id_fkey FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint vip_videos_programme_id_fkey FOREIGN KEY (programme_id) REFERENCES vip_programmes(id) ON DELETE RESTRICT,
  constraint vip_videos_pkey PRIMARY KEY (id)
);
alter table public.vip_videos enable row level security;

create table public.vip_view_readings (
  id bigint generated always as identity not null,
  video_id uuid not null,
  views bigint not null,
  source text,
  read_at timestamp with time zone default now() not null,
  constraint vip_view_readings_video_id_fkey FOREIGN KEY (video_id) REFERENCES vip_videos(id) ON DELETE CASCADE,
  constraint vip_view_readings_pkey PRIMARY KEY (id)
);
alter table public.vip_view_readings enable row level security;

create table public.voucher_nudges_sent (
  challenge_id uuid not null,
  creator_id uuid not null,
  sent_at timestamp with time zone default now() not null,
  points_short numeric,
  constraint voucher_nudges_sent_challenge_id_fkey FOREIGN KEY (challenge_id) REFERENCES challenges(id) ON DELETE CASCADE,
  constraint voucher_nudges_sent_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint voucher_nudges_sent_pkey PRIMARY KEY (challenge_id, creator_id)
);
alter table public.voucher_nudges_sent enable row level security;

